package com.nahui.followupbussiness.identityaccess.adapter.out.security;
import java.util.UUID; import org.junit.jupiter.api.Test; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.data.redis.core.ValueOperations; import static org.mockito.Mockito.*; import static org.assertj.core.api.Assertions.*;
class RedisLogoutAbuseMonitorTest { @Test void storesOnlyHmacKeyAndSixthGlobalIsDeduplicatedWithoutFailure(){var redis=mock(StringRedisTemplate.class);@SuppressWarnings("unchecked") ValueOperations<String,String> values=mock(ValueOperations.class);when(redis.opsForValue()).thenReturn(values);when(values.increment(anyString())).thenReturn(6L);var account=UUID.randomUUID();var decision=new RedisLogoutAbuseMonitor(redis,"01234567890123456789012345678901".getBytes()).recordGlobal(account,UUID.randomUUID());var key=org.mockito.ArgumentCaptor.forClass(String.class);verify(values).increment(key.capture());assertThat(key.getValue()).startsWith("auth:logout:dedupe:").doesNotContain(account.toString());assertThat(decision.deduplicated()).isTrue();var unavailable=mock(StringRedisTemplate.class);when(unavailable.opsForValue()).thenThrow(new IllegalStateException());assertThatCode(()->new RedisLogoutAbuseMonitor(unavailable,"01234567890123456789012345678901".getBytes()).recordGlobal(UUID.randomUUID(),UUID.randomUUID())).doesNotThrowAnyException();} }
